/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { StringManager } from "../../src/i18n/StringManager.js";
import { IntroScreen } from "../../src/intro/IntroScreen.js";
import LightPropagationColors from "../../src/LightPropagationColors.js";
import { LabScreen } from "../../src/lab/LabScreen.js";
import { PolarizationScreen } from "../../src/polarization/PolarizationScreen.js";
import { LightPropagationPreferencesModel } from "../../src/preferences/LightPropagationPreferencesModel.js";
import { WavePlatesScreen } from "../../src/wave-plates/WavePlatesScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();
  const screenNames = stringManager.getScreenNames();

  // Simulation-specific preferences; initial values come from lightPropagationQueryParameters.
  const simPreferences = new LightPropagationPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new IntroScreen({
      // The screen name Property updates automatically when the locale changes
      name: screenNames.introStringProperty,
      tandem: Tandem.ROOT.createTandem("introScreen"),
      backgroundColorProperty: LightPropagationColors.backgroundColorProperty,
    }),
    new PolarizationScreen({
      // The screen name Property updates automatically when the locale changes
      name: screenNames.polarizationStringProperty,
      tandem: Tandem.ROOT.createTandem("polarizationScreen"),
      backgroundColorProperty: LightPropagationColors.backgroundColorProperty,
      preferences: simPreferences,
    }),
    new WavePlatesScreen({
      // The screen name Property updates automatically when the locale changes
      name: screenNames.wavePlatesStringProperty,
      tandem: Tandem.ROOT.createTandem("wavePlatesScreen"),
      backgroundColorProperty: LightPropagationColors.backgroundColorProperty,
    }),
    new LabScreen({
      // The screen name Property updates automatically when the locale changes
      name: screenNames.labStringProperty,
      tandem: Tandem.ROOT.createTandem("labScreen"),
      backgroundColorProperty: LightPropagationColors.backgroundColorProperty,
      preferences: simPreferences,
    }),
  ];

  return { screens, tracked: { LightPropagationColors, stringManager, simPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
